const b = $input.first().json.body || $input.first().json;
const esc = (s) => (s == null || s === '') ? 'NULL' : `'${String(s).replace(/'/g, "''")}'`;
const num = (n) => (n == null || n === '' || isNaN(Number(n))) ? 'NULL' : Number(n);
const lit = (s) => String(s == null ? '' : s).replace(/'/g, "''");
const leads = Array.isArray(b.leads) ? b.leads : [];
const uid = lit(b.line_user_id);
const lineName = b.line_name || b.cust_name || '';
const phone = b.cust_phone || '';

const sqls = [];
for (const L of leads) {
  const detail = JSON.stringify(L.detail || {}).replace(/'/g, "''");
  sqls.push(`INSERT INTO leads (lead_type, model, variant, color, pay_type, down_pct, installment, period, price, cust_name, cust_phone, line_user_id, detail)
VALUES (${esc(L.lead_type)}, ${esc(L.model)}, ${esc(L.variant)}, ${esc(L.color)}, ${esc(L.pay_type)}, ${num(L.down_pct)}, ${num(L.installment)}, ${num(L.period)}, ${num(L.price)}, ${esc(b.cust_name || L.cust_name)}, ${esc(phone || L.cust_phone)}, ${esc(b.line_user_id)}, '${detail}'::jsonb);`);
}
const N = leads.length || 0;
const interest = N ? (leads[0].model || '') : '';
let upsert = '';
if (uid && N > 0) {
  upsert = `WITH old AS (SELECT status AS prev_status FROM customers WHERE line_user_id='${uid}')
INSERT INTO customers (line_user_id, display_name, phone, interest_model, lead_count, last_seen, updated_at)
VALUES ('${uid}', ${esc(lineName)}, ${esc(phone)}, ${esc(interest)}, ${N}, NOW(), NOW())
ON CONFLICT (line_user_id) DO UPDATE SET
  display_name = COALESCE(customers.display_name, NULLIF(EXCLUDED.display_name, '')),
  phone = COALESCE(NULLIF(EXCLUDED.phone, ''), customers.phone),
  interest_model = COALESCE(NULLIF(EXCLUDED.interest_model, ''), customers.interest_model),
  lead_count = customers.lead_count + ${N},
  status = CASE WHEN customers.status IN ('approved','rejected') THEN 'new' ELSE customers.status END,
  assignee = CASE WHEN customers.status IN ('approved','rejected') THEN NULL ELSE customers.assignee END,
  last_seen = NOW(),
  updated_at = NOW()
RETURNING id, (SELECT prev_status FROM old) AS prev_status;`;
}
return [{ json: { sql: sqls.join('\n') + '\n' + upsert, payload: b } }];

const SALES_TOKEN = 'SALES_TOKEN_HERE';
const SALES_GROUP_ID = 'SALES_GROUP_ID_HERE';
const b = $('Build SQL').first().json.payload || {};
let row = {};
try { row = $('Insert').first().json || {}; } catch (e) {}
const custId = row.id || null;
const prevStatus = row.prev_status || null;
const code = custId ? ('PP-' + String(custId).padStart(4, '0')) : 'PP-????';
const uid = b.line_user_id || '';
const custName = (b.line_name || b.cust_name || '').trim() || 'ลูกค้า LINE';
const leads = Array.isArray(b.leads) ? b.leads : [];
const baht = (n) => '฿' + Number(n || 0).toLocaleString('en-US');
const color = '#1eaa5c';
const phone = b.cust_phone ? ('📞 ' + b.cust_phone) : '📞 (รอลูกค้าฝากเบอร์)';

const lines = leads.slice(0, 12).map((L) => {
  const p = L.pay_type === 'cash' ? ('เงินสด ' + baht(L.price)) : ('ผ่อน ' + baht(L.installment) + '/' + (L.period || '-') + 'ด.');
  const sub = [L.variant, L.color].filter(Boolean).join(' ');
  return { type: 'text', text: '• ' + L.model + (sub ? ' (' + sub + ')' : '') + ' · ' + p, size: 'sm', wrap: true, margin: 'sm' };
});

const body = [
  { type: 'box', layout: 'vertical', backgroundColor: color, cornerRadius: '6px', paddingAll: '8px', contents: [{ type: 'text', text: '🟢 ลูกค้าใหม่ · สนใจ ' + leads.length + ' รุ่น', color: '#ffffff', weight: 'bold', size: 'sm' }] },
  { type: 'text', text: '👤 ' + custName, weight: 'bold', size: 'xl', margin: 'md', wrap: true }
];
lines.forEach((l) => body.push(l));
body.push({ type: 'text', text: phone, size: 'sm', margin: 'md' });
body.push({ type: 'text', text: '🔴 รอติดต่อ', size: 'sm', weight: 'bold', color: '#cc0000', margin: 'sm' });

const flex = {
  type: 'flex', altText: 'ลูกค้าใหม่ ' + custName + ' สนใจ ' + leads.length + ' รุ่น',
  contents: {
    type: 'bubble',
    body: { type: 'box', layout: 'vertical', spacing: 'sm', contents: body },
    footer: { type: 'box', layout: 'vertical', spacing: 'sm', contents: [
      { type: 'button', style: 'primary', color: color, height: 'sm', action: { type: 'postback', label: '📞 รับเคส', data: 'action=claim&cid=' + uid, displayText: 'รับเคส ' + custName } },
      { type: 'box', layout: 'horizontal', spacing: 'sm', contents: [
        { type: 'button', style: 'secondary', height: 'sm', action: { type: 'postback', label: '✅ อนุมัติ', data: 'action=approve&cid=' + uid, displayText: 'อนุมัติ ' + custName } },
        { type: 'button', style: 'secondary', height: 'sm', action: { type: 'postback', label: '❌ ไม่ผ่าน', data: 'action=reject&cid=' + uid, displayText: 'ไม่ผ่าน ' + custName } }
      ]},
      { type: 'text', text: code, size: 'xs', color: '#cccccc', align: 'end', margin: 'sm' }
    ]}
  }
};
const configured = SALES_GROUP_ID && SALES_GROUP_ID !== 'SALES_GROUP_ID_HERE' && SALES_TOKEN !== 'SALES_TOKEN_HERE';
const fresh = (!prevStatus) || prevStatus === 'approved' || prevStatus === 'rejected';
const doPush = !!(custId && configured && fresh && leads.length);
return [{ json: { to: SALES_GROUP_ID, messages: [flex], token: SALES_TOKEN, doPush: doPush } }];
